CREATE TEMPORARY VIEW item_cats_31d_${grass_region_without_quote} AS
SELECT
    item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,local_date
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 30) AND ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW keywords_all_ops_1d_${grass_region_without_quote} AS
SELECT
    TRIM(LOWER(keyword)) AS keyword
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND page_type IN ('global_search','search_in_pdp','search_prefill')
    AND page_section IS NULL
    AND target_type in ('item', 'video', 'livestream')
    AND keyword IS NOT NULL
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW keywords_item_id_imp_31d_${grass_region_without_quote} AS
SELECT
    TRIM(LOWER(keyword)) AS keyword
    ,item_id
    ,local_date
    ,SUM(operation_cnt) AS imp_count
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 30) AND ${local_date}
    AND page_type IN ('global_search','search_in_pdp','search_prefill')
    AND page_section IS NULL
    AND target_type in ('item', 'video', 'livestream')
    AND keyword IS NOT NULL
    AND operation = 'impression'
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW keywords_filter_1d_${grass_region_without_quote} AS
SELECT
    a.keyword AS keyword
    ,item_id
    ,local_date
    ,imp_count
FROM
    keywords_all_ops_1d_${grass_region_without_quote} a
LEFT JOIN
    keywords_item_id_imp_31d_${grass_region_without_quote} b
ON
    a.keyword = b.keyword;

--sql_divide_splitter--

CREATE TEMPORARY VIEW keywords_item_cat_${grass_region_without_quote} AS
SELECT
    keyword
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,a.local_date AS local_date
    ,SUM(imp_count) AS imp_count
FROM
    keywords_filter_1d_${grass_region_without_quote} a
LEFT JOIN
    item_cats_31d_${grass_region_without_quote} b
ON
    a.item_id = b.item_id
    AND a.local_date = b.local_date
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW keywords_item_cat_rank_${grass_region_without_quote} AS
SELECT
    keyword
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,ROW_NUMBER() OVER (PARTITION BY keyword ORDER BY local_date DESC, imp_count DESC) AS recency_rank
FROM
    keywords_item_cat_${grass_region_without_quote};

